const uniqueBy = <T,>(values: T[], key: (value: T) => string): T[] => {
  const seen = new Set<string>();
  return values.filter((value) => {
    const id = key(value);
    if (seen.has(id)) return false;
    seen.add(id);
    return true;
  });
};

const profileSection = (item: Bac2ArtsSourceProfile): LessonSection => ({
  title: "المضامين المستخلصة من الملخص المرجعي",
  blocks: [
    { type: "callout", tone: "info", label: "الإشكالية الموجهة", text: item.question },
    ...item.axes.map((axis) => ({ type: "ul" as const, title: axis.title, items: axis.points })),
  ],
});

const profileDocs = (item: Bac2ArtsSourceProfile): LessonDoc[] =>
  item.axes.slice(0, 2).map((axis, index) => ({
    label: `معطيات مستخلصة من الملخص — ${axis.title}`,
    text: axis.points.join(" "),
    questions: [
      {
        q: `استخرج من المعطيات عنصرين يوضحان محور «${axis.title}».`,
        pts: 1,
        answer: axis.points.slice(0, 2).join(" "),
      },
      {
        q: index === 0
          ? "حدد العلاقة بين العوامل والمظاهر أو الأحداث الواردة في المعطيات."
          : "استنتج نتيجة أو تحديًا يترتب عن المعطيات.",
        pts: 1,
        answer: index === 0
          ? `${axis.points[0]} ${axis.points[1] ?? ""}`
          : `${axis.points[axis.points.length - 1] ?? axis.points[0]} ويقتضي ذلك جوابًا يربط الوصف بالتفسير والتركيب.`,
      },
    ],
  }));

/** يدمج الاستخراج المنظم مع المحتوى الموجود دون المساس بأي مسلك آخر. */
export function enrichBac2ArtsContent(content: LessonContent, lessonId: string): LessonContent {
  const item = BAC2_ARTS_SOURCE_PROFILES[lessonId];
  if (!item) return content;

  const glossary = uniqueBy([...content.glossary, ...item.concepts], (value) => value.term);
  const timeline = uniqueBy([...content.timeline, ...item.dates], (value) => `${value.date}|${value.event}`);
  const docs = uniqueBy([...(content.docs ?? []), ...profileDocs(item)], (value) => value.label);
  return {
    ...content,
    coreQuestion: item.question,
    objectives: uniqueBy([...content.objectives, ...item.objectives], (value) => value),
    sections: [...content.sections, profileSection(item)],
    glossary,
    timeline,
    summary: uniqueBy([...content.summary, ...item.summary], (value) => value),
    docs,
  };
}
